typedef float vm_num_t;
typedef unsigned int uint32;

class stringx;
class vm_executable { public: const stringx& get_fullname() const; };
class script_object { public: class instance { public: const stringx& get_name() const; }; };
class vm_thread { public: script_object::instance* get_instance() const; const vm_executable* get_executable() const; };
class stringx {};
stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class vm_stack {
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  void pop(int n) { SP -= n; }
  char* get_SP() const { return SP; }
  bool push(const char* src, int n);
  vm_thread* get_thread() const { return my_thread; }
};

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual ~function();
    virtual bool operator()(vm_stack&, entry_t);
  };
};

class vector3d { public: float x, y, z; };
class region {};
class entity {};
class sector {
  region* my_region;
public:
  region* get_region() const { return my_region; }
};
class terrain {
public:
  sector* find_sector(const vector3d&) const;
};
class world {
  char pad[236];
  terrain the_terrain;
public:
  terrain& get_the_terrain() { return the_terrain; }
};

extern world* g_world_ptr;
bool find_intersection(const vector3d&, const vector3d&, region*, uint32,
                       vector3d*, vector3d*, void*, entity**)
  __asm__("find_intersection__FRC8vector3dT0PQ2t5graph4Z7stringxZP6regionZP6portalZt4less1Z7stringx4nodeUiP8vector3dT4PPQ2t5graph4Z7stringxZP6regionZP6portalZt4less1Z7stringx4nodePP6entity");

#define FI_COLLIDE_WORLD 1
#define FI_COLLIDE_BEAMABLE 4
#define SLF_PARMS stack.pop(sizeof(parms_t)); parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN if (!stack.push((char*)&result,sizeof(result)) ) error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname())
#define SLF_DONE return true

class slf_los_check_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vector3d p0;
    vector3d p1;
  };
  virtual bool operator()(vm_stack& stack, entry_t entry);
};

bool slf_los_check_t::operator()(vm_stack& stack,entry_t entry)
{
  SLF_PARMS;
  vm_num_t result = 1;

  sector *sect = g_world_ptr->get_the_terrain().find_sector(parms->p0);
  if(sect && sect->get_region())
  {
    vector3d hit_pos;
    vector3d hit_norm;
    entity *hit_entity;
    bool hit = find_intersection( parms->p0,
                                  parms->p1,
                                  sect->get_region(),
                                  FI_COLLIDE_WORLD | FI_COLLIDE_BEAMABLE,
                                  &hit_pos,
                                  &hit_norm,
                                  NULL,
                                  &hit_entity
                                );

    if(hit)
      result = 0;
  }
  else
    result = 0;

  SLF_RETURN;
  SLF_DONE;
}
